def main() -> int:
    selected = json.loads(SELECTED.read_text())
    sel_ids = [s["candidate_id"] for s in selected]
    dec_ids = [d[0] for d in DECISIONS]
    if sel_ids != dec_ids:
        raise SystemExit(
            "decision order does not match selection order:\n"
            f"first mismatch at index {next(i for i, (a, b) in enumerate(zip(sel_ids, dec_ids)) if a != b)}"
        )
    out = []
    for i, (cid, action, rationale) in enumerate(DECISIONS, 1):
        out.append({
            "decision_id": f"D-DISC002-B13-{i:04d}",
            "candidate_id": cid,
            "action": action,
            "rationale": rationale,
            "reviewer": REVIEWER,
        })
    with open(OUT, "w", encoding="utf-8") as fh:
        for rec in out:
            fh.write(json.dumps(rec, ensure_ascii=False) + "\n")
    from collections import Counter
    counts = Counter(d[1] for d in DECISIONS)
    print(f"wrote {len(out)} decisions to {OUT}")
    print("actions:", dict(counts))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
